hero.css:
.hero {
  position: relative;
  display: grid;
  place-items: center;
  /* The shell hands the hero the height the footer leaves over; the minimum is
     a floor for very short viewports, not the usual size. */
  flex: 1 1 auto;
  min-height: 26rem;
  padding-block: clamp(3rem, 10vh, 6.5rem) clamp(4rem, 12vh, 7rem);
  padding-inline: var(--gutter);
  overflow: hidden;
  background:
    radial-gradient(125% 95% at 50% 0%, var(--c-foam-100) 0%, transparent 60%),
    var(--color-bg);
}

.hero-inner {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: minmax(0, auto) minmax(0, auto);
  align-items: center;
  justify-content: center;
  gap: clamp(1.25rem, 4vw, 4.5rem);
  width: 100%;
  max-width: var(--content-max);
}

.hero-emblem {
  width: clamp(8rem, 19vw + 4.5vh, 24rem);
  height: auto;
  filter: drop-shadow(0 10px 26px rgb(18 59 73 / 0.12));
  animation: hero-rise 900ms var(--ease-out) both;
}

.hero-copy {
  display: grid;
  gap: clamp(0.1rem, 0.55vw, 0.45rem);
  text-align: start;
  text-wrap: balance;
}

/*
 * The three script lines — eyebrow, country and date — are one treatment, not
 * three. `--script-size` is the single knob each breakpoint turns; the date
 * takes a fixed step down from it so the hierarchy survives every viewport.
 */
.hero-eyebrow,
.hero-country,
.hero-dates {
  --script-size: var(--step-script);

  font-family: var(--font-script);
  font-size: var(--script-size);
  font-weight: 400;
  line-height: 1.3;
  letter-spacing: 0.015em;
  color: var(--color-brand);
  margin-inline-start: 0.12em;
}

.hero-lead,
.hero-city {
  font-family: var(--font-display);
  font-weight: 400;
  line-height: 1.02;
  letter-spacing: -0.005em;
  color: var(--color-accent);
  -webkit-text-stroke: var(--display-stroke) currentColor;
  paint-order: stroke fill;
}

/*
 * Display sizes blend `vw` and `vh` so the headline fills tall portrait
 * screens as convincingly as it fills wide desktops, instead of shrinking to a
 * label with a dead band beneath it.
 */
.hero-lead {
  font-size: clamp(2.5rem, 4.4vw + 1.7vh, 5.8rem);
}

.hero-city {
  font-size: clamp(3.4rem, 6.2vw + 2.4vh, 8rem);
}

.hero-country {
  line-height: 1.35;
  margin-block-start: 0.1em;
}

/*
 * The date is the quietest beat of the four, so it is the same hand as the
 * lines above it, one step smaller. It was a chip and then a marked word; both
 * read as a control parked on the poster rather than as part of it.
 */
.hero-dates {
  font-size: calc(var(--script-size) * 0.8);
  margin-block-start: clamp(0.3rem, 0.9vh, 0.7rem);
}

/* --- entrance ----------------------------------------------------------- */

.hero-reveal {
  animation: hero-rise var(--duration-slow) var(--ease-out) both;
}

.hero-eyebrow {
  animation-delay: 80ms;
}

.hero-lead {
  animation-delay: 180ms;
}

.hero-city {
  animation-delay: 280ms;
}

.hero-country {
  animation-delay: 380ms;
}

.hero-dates {
  animation-delay: 460ms;
}

@keyframes hero-rise {
  from {
    opacity: 0;
    translate: 0 1.25rem;
  }
  to {
    opacity: 1;
    translate: 0 0;
  }
}

/* --- stacked layout ----------------------------------------------------- */

@media (max-width: 52rem) {
  /*
   * Stacked layout: the headline is anchored just above the surf instead of
   * centred in the whole screen, which is what keeps tall phones and portrait
   * tablets from opening a dead band between the type and the water.
   */
  .hero {
    align-items: end;
    padding-block: clamp(2rem, 7vh, 4rem) clamp(5.5rem, 20vh, 11rem);
  }

  .hero-inner {
    grid-template-columns: minmax(0, 1fr);
    justify-items: center;
    gap: clamp(0.75rem, 3.5vw, 1.75rem);
  }

  .hero-copy {
    text-align: center;
    justify-items: center;
  }

  .hero-emblem {
    width: clamp(8.5rem, 40vw, 16rem);
  }

  .hero-lead {
    font-size: clamp(2.1rem, 11.5vw, 3.8rem);
  }

  .hero-city {
    font-size: clamp(2.75rem, 15vw, 5rem);
  }

  .hero-eyebrow,
  .hero-country,
  .hero-dates {
    --script-size: clamp(1.05rem, 5vw, 1.75rem);

    margin-inline: 0;
  }
}

/* Very short viewports (landscape phones): the emblem shrinks first. */
@media (max-height: 34rem) {
  .hero {
    align-items: center;
    min-height: 0;
    padding-block: 1rem 3rem;
  }

  .hero-emblem {
    width: clamp(5rem, 14vw, 9rem);
  }

  .hero-lead {
    font-size: clamp(1.9rem, 5vw, 3rem);
  }

  .hero-city {
    font-size: clamp(2.4rem, 6.6vw, 4rem);
  }

  .hero-eyebrow,
  .hero-country,
  .hero-dates {
    --script-size: clamp(0.95rem, 2.2vw, 1.4rem);
  }
}

/* Short portrait phones need a smooth scale between the compact and stacked
   layouts. Using viewport height here avoids a jump at the landscape-phone
   breakpoint while keeping the copy clear of both the canopy and the surf. */
@media (orientation: portrait) and (max-width: 40rem) and (max-height: 42rem) {
  .hero {
    align-items: end;
    padding-block: clamp(1.25rem, 5vh, 2rem) clamp(7rem, 30vh, 11rem);
  }

  .hero-inner {
    gap: clamp(0.5rem, 2.5vh, 0.9rem);
  }

  .hero-emblem {
    width: clamp(5rem, min(40vw, calc(30vh - 4rem)), 8.5rem);
  }

  .hero-lead {
    font-size: clamp(1.9rem, min(11.5vw, calc(4.4vh + 0.6rem)), 2.7rem);
  }

  .hero-city {
    font-size: clamp(2.4rem, min(15vw, calc(6vh + 0.6rem)), 3.5rem);
  }

  .hero-eyebrow,
  .hero-country,
  .hero-dates {
    --script-size: clamp(0.95rem, min(5vw, calc(2.2vh + 0.3rem)), 1.2rem);
  }
}

hero-decor.css:
/*
 * Placement for the decorative layer.
 *
 * Sizes use `clamp()` against `vmax` so the frame keeps its proportions from a
 * 320px phone to an ultrawide display — `vw` alone collapses the corners on
 * tall portrait screens. Crowded pieces drop out at the breakpoints where they
 * stop reading rather than being shrunk into noise.
 */

.hero-decor {
  position: absolute;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
  z-index: 0;
}

.hero-decor-item {
  position: absolute;
  /* Fallback size: a piece that forgets its own `width` degrades to a small
     shape instead of stretching across the whole hero. */
  width: 6rem;
  height: auto;
  will-change: transform;
}

/* --- water and beach ---------------------------------------------------- */

.hero-decor-shoreline {
  position: absolute;
  inset-inline: 0;
  bottom: 0;
  width: 100%;
  height: clamp(9.5rem, 30vh, 27rem);
}

.hero-decor-shoreline [data-compact-bands] {
  display: none;
}

.hero-decor-shoreline path {
  --wave-x: 0.9%;
  --wave-y: -0.7%;
  --wave-stretch: 1.026;

  transform-box: fill-box;
  transform-origin: center bottom;
  animation: hero-decor-tide-pulse var(--duration-tide-cycle) var(--ease-out) infinite;
  will-change: transform;
}

.hero-decor-shoreline path:nth-child(1) {
  --wave-x: 0.8%;
  --wave-y: -0.55%;
  --wave-stretch: 1.022;
}

.hero-decor-shoreline path:nth-child(2) {
  --wave-x: 0.9%;
  --wave-y: -0.7%;
  --wave-stretch: 1.026;
  animation-delay: var(--duration-fast);
}

.hero-decor-shoreline path:nth-child(3) {
  --wave-x: 1.05%;
  --wave-y: -0.85%;
  --wave-stretch: 1.03;
  animation-delay: calc(2 * var(--duration-fast));
}

.hero-decor-shoreline path:nth-child(4) {
  --wave-x: 1.2%;
  --wave-y: -1%;
  --wave-stretch: 1.035;
  animation-delay: calc(3 * var(--duration-fast));
}

.hero-decor-sand {
  position: absolute;
  right: 0;
  bottom: 0;
  width: clamp(15rem, 38vw, 52rem);
  height: auto;
}

.hero-decor-sand [data-surf] > path {
  --wash-x: 2.2%;
  --wash-y: 1.2%;
  --wash-scale: 0.975;

  transform-box: fill-box;
  transform-origin: right center;
  animation: hero-decor-surf-wash var(--duration-surf-wash) var(--ease-out) infinite;
  will-change: transform, opacity;
}

.hero-decor-sand [data-surf] > path:nth-child(2) {
  --wash-x: 2.8%;
  --wash-y: 1.7%;
  --wash-scale: 0.97;
  animation-delay: var(--duration-fast);
}

.hero-decor-sand [data-surf] > path:nth-child(3) {
  --wash-x: 3.4%;
  --wash-y: 2.2%;
  --wash-scale: 0.965;
  animation-delay: calc(2 * var(--duration-fast));
}

.hero-decor-sand [data-waterline] {
  animation: hero-decor-waterline-wash var(--duration-surf-wash) var(--ease-out) infinite;
}

.hero-decor-rock {
  bottom: clamp(-1.25rem, -1.5vh, -0.25rem);
  left: 57.5%;
  width: clamp(6rem, 13.5vw, 12rem);
  transform-origin: 50% 88%;
  animation: hero-decor-rock-bob var(--duration-rock-bob) var(--ease-out) infinite alternate;
}

/* --- jungle ------------------------------------------------------------- */

.hero-decor-palm-tree-far {
  right: 5%;
  bottom: clamp(7rem, 25vh, 17rem);
  width: clamp(4rem, 7vmax, 9rem);
}

.hero-decor-palm-tree-near {
  right: -1%;
  bottom: clamp(7.5rem, 25vh, 18rem);
  width: clamp(7rem, 12vmax, 16rem);
}

/* --- background texture ------------------------------------------------- */

.hero-decor-traces {
  position: absolute;
  height: auto;
  color: var(--c-ocean-300);
  opacity: 0.26;
}

.hero-decor-traces-top-left {
  top: 3%;
  left: 20%;
  width: clamp(11rem, 24vw, 26rem);
}

.hero-decor-traces-left {
  top: 22%;
  left: -4%;
  width: clamp(11rem, 20vw, 21rem);
}

.hero-decor-traces-lower-left {
  top: 49%;
  left: 11%;
  width: clamp(9rem, 16vw, 17rem);
  opacity: 0.2;
  transform: rotate(180deg);
}

.hero-decor-traces-right {
  top: 36%;
  right: -6%;
  width: clamp(12rem, 22vw, 22rem);
  transform: scaleX(-1);
}

/* --- canopy -------------------------------------------------------------
 * Every frond hangs from the top edge with its stem off canvas.
 *
 * **Nothing here may reach the headline.** The copy column is centred and at
 * most `--content-max` wide, so on a 1440px viewport it ends around 16% from
 * the right edge — a frond drifting into that band sits behind the type and
 * muddies it, even though the text paints on top.
 *
 * `transform-origin` is the stem's base, not the box centre: rotating about the
 * centre swings a large frond right out of the viewport, which is exactly the
 * bug this replaced. `leaf-frond-02` rests pointing right (base at its left
 * edge); `leaf-frond-01` rests pointing up-right (base at its bottom-left).
 */

.hero-decor-leaf-top-left {
  top: -6%;
  left: 0%;
  width: clamp(10rem, 17vmax, 22rem);
  transform-origin: 5% 50%;
  transform: rotate(64deg);
}

.hero-decor-leaf-top-left-mid {
  top: -8%;
  left: 15%;
  width: clamp(7rem, 12vmax, 15rem);
  transform-origin: 5% 50%;
  transform: rotate(96deg);
}

.hero-decor-leaf-top-left-accent {
  top: -4%;
  left: 26%;
  width: clamp(4.5rem, 7.5vmax, 9rem);
  transform-origin: 8% 92%;
  transform: rotate(176deg);
}

.hero-decor-leaf-top-right {
  top: -8%;
  right: 1%;
  width: clamp(9rem, 15vmax, 20rem);
  transform-origin: 5% 50%;
  transform: rotate(122deg);
}

.hero-decor-leaf-top-right-accent {
  top: -5%;
  right: -4%;
  width: clamp(6rem, 9vmax, 11rem);
  transform-origin: 8% 92%;
  transform: rotate(176deg);
}

/* --- reef --------------------------------------------------------------- */

.hero-decor-coral-teal {
  bottom: 0;
  left: -2%;
  width: clamp(6.5rem, 12vmax, 15rem);
}

.hero-decor-coral-red {
  bottom: 0;
  left: 7%;
  width: clamp(4.5rem, 8vmax, 10rem);
}

.hero-decor-coral-fan {
  bottom: 0;
  left: 13%;
  width: clamp(5rem, 9vmax, 11rem);
}

/* --- foreground --------------------------------------------------------- */

.hero-decor-feather-right {
  right: -3%;
  bottom: -18%;
  width: clamp(7rem, 13vmax, 16rem);
  transform: rotate(38deg) scaleX(-1);
}

/* --- motion ------------------------------------------------------------- */

.hero-decor-float {
  animation: hero-decor-sway 9s var(--ease-out) infinite alternate;
}

.hero-decor-float-slow {
  animation: hero-decor-sway 13s var(--ease-out) infinite alternate-reverse;
}

@keyframes hero-decor-sway {
  from {
    translate: 0 0;
    rotate: -1.1deg;
  }
  to {
    translate: 0 -0.7rem;
    rotate: 1.1deg;
  }
}

@keyframes hero-decor-tide-pulse {
  0%,
  52%,
  100% {
    transform: translate3d(calc(-1 * var(--wave-x)), 0, 0) scaleX(1.04) scaleY(1)
      skewX(0deg);
  }

  12% {
    transform: translate3d(calc(-0.35 * var(--wave-x)), var(--wave-y), 0) scaleX(1.045)
      scaleY(var(--wave-stretch)) skewX(-0.4deg);
  }

  26% {
    transform: translate3d(calc(0.35 * var(--wave-x)), calc(-0.3 * var(--wave-y)), 0)
      scaleX(1.042) scaleY(calc(2 - var(--wave-stretch))) skewX(0.35deg);
  }

  40% {
    transform: translate3d(var(--wave-x), calc(0.15 * var(--wave-y)), 0) scaleX(1.04)
      scaleY(1.006) skewX(0deg);
  }
}

@keyframes hero-decor-surf-wash {
  0%,
  100% {
    opacity: 0.68;
    transform: translate3d(calc(-1 * var(--wash-x)), calc(-0.5 * var(--wash-y)), 0)
      scaleX(1.035);
  }

  42%,
  58% {
    opacity: 1;
    transform: translate3d(var(--wash-x), var(--wash-y), 0) scaleX(var(--wash-scale));
  }
}

@keyframes hero-decor-waterline-wash {
  0%,
  100% {
    opacity: 0.76;
    stroke-width: 7;
  }

  42%,
  58% {
    opacity: 1;
    stroke-width: 10;
  }
}

@keyframes hero-decor-rock-bob {
  from {
    transform: translateY(0) rotate(-0.35deg);
  }
  to {
    transform: translateY(-0.35rem) rotate(0.35deg);
  }
}

@media (prefers-reduced-motion: reduce) {
  .hero-decor-shoreline path,
  .hero-decor-sand [data-surf] > path,
  .hero-decor-sand [data-waterline],
  .hero-decor-rock {
    animation: none;
    transform: none;
  }
}

/* --- density per breakpoint --------------------------------------------- */

@media (max-width: 64rem) {
  .hero-decor-traces-top-left {
    left: 12%;
    opacity: 0.8;
  }

  .hero-decor-shoreline [data-wide-bands] {
    display: none;
  }

  .hero-decor-shoreline [data-compact-bands] {
    display: inline;
  }
}

@media (max-width: 52rem) {
  .hero-decor-traces-left,
  .hero-decor-traces-lower-left {
    display: none;
  }

  .hero-decor-shoreline {
    height: clamp(8.5rem, 26vh, 18rem);
  }

  .hero-decor-sand {
    width: clamp(20rem, 58vw, 30rem);
  }

  .hero-decor-palm-tree-far {
    right: 10%;
    bottom: clamp(8rem, 15vh, 10rem);
    width: clamp(3.25rem, 6vmax, 4rem);
  }

  .hero-decor-palm-tree-near {
    right: 1%;
    bottom: clamp(7.5rem, 14vh, 9rem);
    width: clamp(5rem, 9vmax, 8rem);
  }
}

/* Phones: keep only the pieces that frame the corners. */
@media (max-width: 40rem) {
  .hero-decor-shoreline {
    height: clamp(8rem, 24vh, 14rem);
  }

  .hero-decor-leaf-top-left-accent,
  .hero-decor-leaf-top-right-accent,
  .hero-decor-leaf-top-left-mid,
  .hero-decor-feather-right,
  .hero-decor-traces-right {
    display: none;
  }

  .hero-decor-traces-top-left {
    top: 7%;
    left: 6%;
    width: 56vw;
    opacity: 0.18;
  }

  .hero-decor-leaf-top-left {
    top: -5%;
    left: -4%;
    width: 12rem;
  }

  .hero-decor-leaf-top-right {
    top: -7%;
    right: -46%;
    width: 11.5rem;
  }

  .hero-decor-coral-teal {
    left: -3%;
    width: 5.5rem;
  }

  .hero-decor-coral-red {
    left: 9%;
    bottom: 0;
    width: 3.75rem;
  }

  .hero-decor-coral-fan {
    left: 21%;
    bottom: 0;
    width: 4rem;
  }

  .hero-decor-palm-tree-far {
    right: 11%;
    bottom: 5.75rem;
    width: 3rem;
  }

  .hero-decor-palm-tree-near {
    right: 0;
    bottom: 5.5rem;
    width: 3.75rem;
  }

  .hero-decor-sand {
    width: clamp(17rem, 74vw, 19rem);
  }

  .hero-decor-rock {
    bottom: 0.35rem;
    left: 42%;
    width: 2.6rem;
  }
}

/* Landscape phones and other very short viewports: shrink the frame so the
   headline keeps the stage. */
@media (max-height: 34rem) {
  .hero-decor-shoreline {
    height: 5.5rem;
  }

  .hero-decor-sand {
    width: 12rem;
    height: auto;
  }

  .hero-decor-leaf-top-left {
    top: -6%;
    width: 7.5rem;
  }

  .hero-decor-leaf-top-right {
    top: -14%;
    right: -2%;
    width: 7rem;
  }

  .hero-decor-leaf-top-left-accent,
  .hero-decor-leaf-top-left-mid,
  .hero-decor-feather-right,
  .hero-decor-rock {
    display: none;
  }

  .hero-decor-coral-teal {
    width: 4.5rem;
  }

  .hero-decor-coral-red {
    left: 8%;
    width: 3rem;
  }

  .hero-decor-coral-fan {
    left: 16%;
    width: 3.25rem;
  }

  .hero-decor-palm-tree-far {
    right: 16%;
    bottom: 3.5rem;
    width: 2.5rem;
  }

  .hero-decor-palm-tree-near {
    right: 3%;
    bottom: 3.75rem;
    width: 3rem;
  }
}

/* Keep the upper frame clear of the emblem on short portrait phones. */
@media (orientation: portrait) and (max-width: 40rem) and (max-height: 42rem) {
  .hero-decor-leaf-top-left {
    top: -6%;
    width: clamp(7.5rem, 24vh, 9.5rem);
  }

  .hero-decor-leaf-top-right {
    top: -8%;
    right: -34%;
    width: clamp(7rem, 22vh, 9rem);
  }
}
